package W1 {
  import Swaml::Platform;
  component def OsTask specializes Process {
    const attribute periodUs: uint = 0;
    const attribute responseUs: uint = 0;
    const attribute priority: uint = 0;
    const attribute category: string = "basic";
  }
  component def Cpu specializes Partition {
    component isr: OsTask { redefines const attribute priority: uint = 60; redefines const attribute category: string = "isr2"; }
    component low: OsTask { redefines const attribute priority: uint = 1; redefines const attribute periodUs: uint = 10000; }
    component high: OsTask { redefines const attribute priority: uint = 50; redefines const attribute periodUs: uint = 10000; }
  }
  component def Board specializes Platform {
    component cpu0: Cpu;
    component cpu1: Cpu;
  }
  port def P { provides event e(n: int); }
  component def Producer { port tx: P; attribute n: int = 0; operation tick() { n = n + 1; publish tx.e(n); } schedule { on every 10ms tick(); } }
  component def Consumer { reversed port inp: P; attribute log: int = 0; operation a() { log = log * 10 + 1; } operation b() { log = log * 10 + 2; } operation take(v: int) { log = log * 10 + 3; } operation after1() { log = log * 10 + 4; }
    schedule { on every 10ms a(); on every 10ms b(); on receive inp.e(v) take(v); after a after1(); } }
  component Demo { component p: Producer; component c: Consumer; component q: Consumer; connect (p.tx, c.inp); connect (p.tx, q.inp); }
  component hw: Board;
  deployment D of Demo on hw {
    deploy p on cpu0.isr;
    deploy c on cpu0.low;
    deploy q on cpu1.high;
  }
}

package Swaml::Os {
  import Swaml::Platform;
  enum TaskKind { basic, extended, isr }
  component def Core specializes Node { }
  component def Task specializes Process {
    const attribute kind: TaskKind = TaskKind.basic;
    const attribute priority: uint = 0;
    const attribute preemptive: bool = true;
    const attribute periodNs: uint = 0;
    const attribute responseNs: uint = 0;
  }
}
package W2 {
  import Swaml::Platform;
  import Swaml::Os;
  component def Cpu specializes Core {
    component t1: Task { redefines const attribute priority: uint = 5; redefines const attribute periodNs: uint = 10000000; }
    component t2: Task { redefines const attribute priority: uint = 5; redefines const attribute periodNs: uint = 10000000; }
    component irq: Task { redefines const attribute kind: TaskKind = TaskKind.isr; redefines const attribute periodNs: uint = 1000; redefines const attribute preemptive: bool = false; redefines const attribute responseNs: uint = 5000000; }
  }
  component def Board specializes Platform {
    component cpu0: Cpu;
    component cpu1: Cpu;
  }
  component def C { attribute log: int = 0; operation a() { log = log * 10 + 1; } operation b() { log = log * 10 + 2; } operation w() { wait 1ms; log = log + 100; }
    schedule { on every 15ms a(); on start b(); on every 10ms w() deadline 1ms; } }
  component Demo { component x: C; component y: C; }
  component hw: Board;
  deployment D of Demo on hw {
    deploy x on cpu0.t1;
    deploy y on cpu0.irq;
  }
}

package Swaml::Os {
  import Swaml::Platform;
  component def Core specializes Node { }
  component def Task specializes Process { const attribute priority: uint = 0; }
}
package W3 {
  import Swaml::Platform;
  component def Cpu specializes Swaml::Os::Core {
    component t: Swaml::Os::Task;
    component u: Swaml::Os::Task;
  }
  component def Board specializes Platform {
    component cpu0: Cpu;
    component cpu1: Cpu;
  }
  component def C { attribute n: int = 0; operation a() { n = n + 1; } schedule { on every 10ms a(); } }
  component Demo { component x: C; component y: C[2]; }
  component hw: Board;
  deployment D of Demo on hw {
    deploy on cpu0;
    deploy x on cpu0.t;
    deploy y on cpu1.u;
    deploy y[1] on cpu0.u;
  }
}

package W4 {
  import Swaml::Platform;
  enum TaskKind { basic, extended, isr }
  component def Core specializes Node { const attribute kind: TaskKind = TaskKind.isr; }
  component def Task specializes Process { const attribute priority: uint = 3; const attribute preemptive: bool = false; const attribute periodNs: uint = 7; const attribute responseNs: uint = 1; }
  component def Cpu specializes Core { component task: Task; component other: Task; }
  component def Board specializes Platform {
    component cpu0: Cpu;
    component cpu1: Cpu;
  }
  component def Worker { attribute priority: uint = 0; attribute kind: TaskKind = TaskKind.basic; operation Task() { priority = priority + 1; } operation Core() { kind = TaskKind.extended; } schedule { on every 5ms Task(); on start Core(); } }
  component Demo { component w: Worker; component v: Worker; }
  component hw: Board;
  deployment D of Demo on hw {
    deploy w on cpu0.task;
    deploy v on cpu1.other;
  }
}

package W5 {
  import Swaml::Platform;
  component def C { attribute n: int = 0; operation tick() { n = n + 1; } operation helper() { } schedule { on every 10ms tick(); } }
  component Demo { component c: C; }
  component def Box specializes Node { component slot: Node; }
  component n1: Box;
  deployment D of Demo on n1 {
    deploy on slot;
    deploy c.helper on slot;
  }
}

package W6 {
  import Swaml::Platform;
  port def P { provides event e(); }
  component def C { port tx: P; attribute n: int = 0; operation tick() { operation inner() { } n = n + 1; } schedule { on every 10ms tick(); } }
  component Demo { component c: C; component fam: C[2]; }
  component def Box specializes Node { component slot: Node; }
  component n1: Box;
  deployment D of Demo on n1 {
    deploy c.n on slot;
    deploy c.tx on slot;
    deploy c.tick.inner on slot;
    deploy c.missing on slot;
    deploy fam.tick[0] on slot;
    deploy c on slot.nothing;
  }
}

package W7 {
  import Swaml::Platform;
  component def C { attribute n: int = 0; operation tick() { n = n + 1; } operation idle() { } schedule { on every 10ms tick(); } }
  component Demo { component fam: C[3]; }
  component def Box specializes Node { component a: Node; component b: Node; }
  component n1: Box;
  deployment D of Demo on n1 {
    deploy fam on a;
    deploy fam.idle on b;
    deploy fam[1].idle on b;
    deploy fam[1] on b;
    deploy fam[1] on a;
  }
}

package W8 {
  import Swaml::Platform;
  component def Leaf { attribute n: int = 0; operation boot() { n = n + 1; } operation tick() { n = n + 10; } schedule { on start boot(); on every 1ms tick(); after boot tick(); } }
  component def Mid { component leaves: Leaf[2]; component solo: Leaf; }
  component Demo { component mids: Mid[2]; component lone: Leaf; }
  component def Ecu specializes Node { component os: Process[2]; }
  component def Car specializes Platform { component ecus: Ecu[2]; }
  component car: Car;
  deployment D of Demo on car {
    deploy mids on ecus[0].os[0];
    deploy mids[1] on ecus[1].os[1];
    deploy mids[1].leaves on ecus[1].os[0];
    deploy mids[1].leaves[0] on ecus[0].os[1];
  }
}

package W9 {
  import Swaml::Platform;
  port def P { provides event e(n: int); requires operation ask(v: int) returns int; }
  component def Server { reversed port inp: P; attribute log: int = 0; operation take(v: int) { log = log * 10 + v; } operation answer(v: int) returns int { return v + 1; } schedule { on receive inp.e(v) take(v); on call inp.ask(v) answer(v); } }
  component def Client { port tx: P; attribute got: int = 0; operation go() { publish tx.e(1); got = tx.ask(4); publish tx.e(2); } operation tock() { publish tx.e(3); } schedule { on every 10ms go(); on every 10ms tock(); after go tock(); } }
  component def Pair { component s: Server; component c: Client; connect (c.tx, s.inp); }
  component pair: Pair;
  component def Box specializes Node { component hi: Process; component lo: Process; }
  component box: Box;
  deployment D of pair on box {
    deploy s on lo;
    deploy c on hi;
  }
  test Order of pair {
    wait 25ms;
    assert pair.c.got == 5;
    assert pair.s.log > 0;
  }
}

package W10 {
  import Swaml::Platform;
  component def C { operation isr() { } operation task() { } schedule { on start isr(); on every 1ms task(); } }
  component Demo { component core: C; }
  component def Plain { }
  component plain: Plain;
  component n1: Node;
  deployment One of Demo on n1 { deploy core on n1; }
  deployment Two of Demo on plain { deploy core on n1; }
}

package W11 {
  import Swaml::Platform;
  component def Proc specializes Process { const attribute priority: uint = 0; const attribute category: string = "basic"; }
  component def Cpu specializes Partition { component bg: Proc { redefines const attribute priority: uint = 1; redefines const attribute category: string = "extended"; } component fast: Proc { redefines const attribute priority: uint = 30; } }
  component def Board specializes Platform {
    component cpu0: Cpu;
    component cpu1: Cpu;
  }
  port def S { requires operation get() returns int; }
  component def Store { reversed port api: S; attribute v: int = 7; operation get() returns int { wait 2ms; return v; } schedule { on call api.get() get(); } }
  component def User { port api: S; attribute seen: int = 0; attribute ticks: int = 0; operation poll() { seen = api.get(); } operation tick() { ticks = ticks + 1; } schedule { on every 5ms poll(); on every 5ms tick(); } }
  component Demo { component store: Store; component user: User; connect (user.api, store.api); }
  component hw: Board;
  deployment D of Demo on hw {
    deploy store on cpu1.bg;
    deploy user on cpu0.fast;
  }
}

package Swaml::Os {
  enum TaskKind { basic }
  component def Os { }
}
package W12 {
  import Swaml::Platform;
  import Swaml::Os;
  component def Cpu specializes Node { component t: Os; }
  component Demo { component o: Os; }
  component hw: Cpu;
  deployment D of Demo on hw { deploy o on t; }
}

package W13 {
  import Swaml::Platform;
  component def C { attribute n: int = 0; operation step() { n = n + 1; } schedule { on every 2ms step(); } }
  component Demo { component step: C; attribute n: int = 0; operation boot() { n = 1; } schedule { on start boot(); } }
  component def Box specializes Node { component inner: Node; }
  component box: Box;
  deployment D of Demo on box {
    deploy on inner;
    deploy step on box2;
  }
}

package W14 {
  import Swaml::Platform;
  port def P { provides event e(n: int); }
  component def Src { port tx: P; attribute k: int = 0; operation boot() { k = 1; publish tx.e(k); } operation tick() { k = k + 1; publish tx.e(k); } schedule { on start boot(); on every 4ms tick(); } }
  component def Sink { reversed port inp: P; const attribute priority: uint = 9; attribute log: int = 0; operation take(v: int) { log = log * 10 + v % 10; } operation tick() { log = log + 1000; } operation chain() { log = log + 100000; } schedule { on receive inp.e(v) take(v); on every 4ms tick(); after tick chain(); } }
  component Demo { component s: Src; component a: Sink; component b: Sink { redefines const attribute priority: uint = 1; } connect (s.tx, a.inp); connect (s.tx, b.inp); }
  component def Box specializes Node { component t1: Process; component t2: Process; }
  component box: Box;
  deployment D of Demo on box {
    deploy s on t1;
    deploy a on t2;
    deploy b on t1;
  }
}
